choose.when:
AND EXISTS (SELECT 1 FROM xsy_purchase_receipt_item_lot rl JOIN xsy_purchase_receipt_item ri ON ri.id =
    rl.purchase_receipt_item_id JOIN xsy_purchase_receipt pr ON pr.id = ri.purchase_receipt_id WHERE
    rl.lot_id = r.lot_id AND pr.deleted = FALSE AND pr.warehouse_id IN

    #{warehouseId}

)

mapper.select:

WHERE r.lot_id = #{lotId}
    AND r.status = 'PUBLISHED'
ORDER BY r.inspection_date DESC, r.id DESC
